SETUP
// ============================================================================
#set page(
  paper: {page_size},
  flipped: {page_flipped},
  margin: 0.4in,
  fill: cream,
)

// ============================================================================
// TYPOGRAPHY
// ============================================================================
#set text(
  // Faces the package bundles (stellium/data/fonts), so an atlas renders the same
  // everywhere. It used to name "Crimson Pro" and "Cinzel Decorative", neither of
  // which ships — and it pointed font_paths at a directory that never existed, so
  // every one of these fell through to whatever the host happened to have.
  font: ("EB Garamond", "Noto Sans Symbols 2", "Noto Sans Symbols", "Symbola", "Georgia", "serif"),
  size: 11pt,
  fill: text-dark,
)
"""

    def _render_section_divider(self, section_name: str, count: int) -> str:
        """Render a section divider page."""
        return f"""
// ============================================================================
// SECTION: {section_name}
// ============================================================================
#pagebreak()
#align(center + horizon)[
  #box(width: 70%)[
    #line(length: 100%, stroke: 0.75pt + gold)
    #v(0.3in)
    #text(font: "Cinzel", size: 32pt, fill: primary, tracking: 1.5pt)[
      {self._escape(section_name)}
    ]
    #v(0.15in)
    #text(size: 14pt, fill: secondary)[
      {count} {"chart" if count == 1 else "charts"}
    ]
    #v(0.3in)
    #line(length: 100%, stroke: 0.75pt + gold)
  ]
]
#pagebreak()
"""

    def _render_title_page(self) -> str:
        """Render the title page."""
        title = self._escape(self.config.title or "Chart Atlas")

        return f"""
// ============================================================================
// TITLE PAGE
// ============================================================================
#align(center + horizon)[
  #box(width: 70%)[
    #line(length: 100%, stroke: 0.75pt + gold)
    #v(0.2in)
    #text(font: "Cinzel", size: 28pt, fill: primary, tracking: 1.5pt)[
      {title}
    ]
    #v(0.2in)
    #line(length: 100%, stroke: 0.75pt + gold)
  ]
]

#v(1fr)

#align(center)[
  #text(font: "Cinzel", size: 9pt, fill: accent, style: "italic")[
    Generated with Stellium
  ]
]

#pagebreak()
"""

    def _render_chart_page(self, svg_path: str, index: int) -> str:
        """
        Render a single chart page.

        Args:
            svg_path: Path to chart SVG file
            index: Chart index

        Returns:
            Typst markup for the chart page
        """
        # Reference the SVG by its basename. The SVG lives inside
        # self._temp_dir (see _generate_chart_svg) which is also the Typst
        # project root, so Typst will resolve the image relative to the .typ
        # source file in the same directory.
        rel_path = os.path.basename(svg_path).replace("\\", "/")

        # Use align center+horizon to center the chart on the page
        # width: 100% and height: 100% with fit: contain ensures it fills
        # the page while maintaining aspect ratio
        return f"""
// Chart {index + 1}
#align(center + horizon)[
  #image("{rel_path}", width: 100%, height: 100%, fit: "contain")
]
#pagebreak()
"""

    def _escape(self, text: str) -> str:
        """Escape text for Typst."""
        if not text:
            return ""
        # Escape special Typst characters
        text = text.replace("\\", "\\\\")
        text = text.replace("#", "\\#")
        text = text.replace("$", "\\$")
        text = text.replace("@", "\\@")
        text = text.replace("<", "\\<")
        text = text.replace(">", "\\>")
        text = text.replace("[", "\\[")
        text = text.replace("]", "\\]")
        text = text.replace("{", "\\{")
        text = text.replace("}", "\\}")
        text = text.replace("_", "\\_")
        text = text.replace("*", "\\*")
        text = text.replace('"', '\\"')
        return text
